jQuery(document).ready(function($){"use strict";$(".affi-dropdown").each(function(){let placeholder=$(this).attr("placeholder");$(this).viDropdown({placeholder:placeholder})});$(".affi-set-user-select2").select2({closeOnSelect:true,placeholder:"Search for user",ajax:{url:"admin-ajax.php?action=affi_search_affiliate_user",dataType:"json",type:"GET",quietMillis:50,delay:250,data:function(params){return{nonce:affiParams.nonce,keyword:params.term}},processResults:function(data){return{results:data}},cache:true},escapeMarkup:function(markup){return markup},minimumInputLength:1}).on("select2:open",function(e){}).on("select2:selecting",function(e){set_user_payment(e.params.args.data.id)}).on("select2:unselecting",function(e){});function set_user_payment(user_id){$.ajax({url:affiParams.ajaxUrl,type:"POST",data:{nonce:affiParams.nonce,action:"affi_affiliate_payment_info",aff_id:user_id},success(p_data){$("#affi_referral_payment").val(p_data.data);if(p_data.status){}else{if(p_data.message){alert(p_data.message)}}}})}});